import base64
import json

NOTES = 'https://api.hubapi.com/crm/v3/objects/contacts/notes'


def add_contact_note(ctx, args):
    encoded = base64.urlsafe_b64encode(str(args.get('text', '')).encode()).decode()
    body = {'id': args.get('contact_id'), 'note_b64': encoded}
    result = ctx.call_tool('api_fetch', {'method': 'POST', 'url': NOTES, 'body': json.dumps(body)})
    return result.output
